function automatic_page_down() {
// ==UserScript==
// @name         自动拼接下一页
// @namespace    https://viayoo.com/
// @version      0.1
// @homepageURL  https://app.viayoo.com/addons/32
// @run-at       document-start
// @match        *
// @grant        none
// ==/UserScript==
/*
 * @name: 自动拼接下一页
 * @Author: 谷花泰
 * @version: 1.0
 * @description: 在原基础上经过一部分的修改，不通用
 * @include: *
 * @createTime: 2019-11-16 23:10:18
 * @updateTime: 2019-11-17 07:33:04
 */ (function() {
    /* 执行判断 */
    const key = encodeURIComponent('自动拼接下一页:执行判断');
    if (window[key]) {
        return;
    };
    window[key] = true;

    class AutoNextPage {
        /**
         * 初始化配置
         */
        constructor(_configs) {
            const that = this;
            this.configs = _configs;
            /* 最终配置  */
            this.config = {};

            /* 是否执行代码 */
            const canLoad = this.configs.some(config => {
                if (that.siteInList(config.sites)) {
                    that.config = config;
                };
                return that.siteInList(config.sites);
            });
            if (!canLoad) {
                return;
            };

            /* 添加样式 */
            this.addStyle(this.config.style || '');

            /* 保存获取链接的方法 */
            this._getNextPageUrl = this.config.getNextPageUrl || this.getNextPageUrl;

            /* 保存获取链接的方法 */
            this._getPreviousPageUrl = this.config.getPreviousPageUrl || this.getPreviousPageUrl;


            /* 请求状态判断 */
            this.isRequesting = false;

            /* 上一次的文档高度 */
            this.lastScrollHeight = top.document.documentElement.scrollHeight;
            this.init();
        };
        /**
         * 监听滚动
         */
        init() {
            const html = top.document.documentElement;

            /* 刚进来直接加载下一页 */
            console.log('拼接下一页 初始化');
            this.loadNextPage();
            this.loadPreviousPage();
            window.addEventListener('scroll', this.debounce(() => {
                if (html.scrollTop >= (this.lastScrollHeight - 500)) {
                    this.loadNextPage();
                };

                // 检查是否滚动到顶部
                if (html.scrollTop === 0) {
                    // 执行滑到顶部时的操作
                    this.loadPreviousPage();
                    // alert("123");
                };
            }, 10));
        };
        /**
         * 判断网站是否在名单内，支持正则
         */
        siteInList(sites) {
            const hostname = window.location.hostname;
            const result = sites.some(site => {
                if (hostname.match(site)) {
                    return true;
                }
                return false;
            });
            return result;
        };
        /**
         * 默认获取下一页链接的方法
         */
        getNextPageUrl() {
            const nextPageNodes = document.querySelectorAll('a.bg_f.b_ok');
            const nextPageNode = nextPageNodes[nextPageNodes.length - 1];
            return nextPageNode && nextPageNode.getAttribute('href') || '';
        };


        /**
         * 默认获取上一页链接的方法
         */
        getPreviousPageUrl() {
            const currentURL = window.location.href;
            let href = '';
            if (currentURL.indexOf('page=') > 0) {
                href = currentURL.match(/page=(\d+)/)[1];

            } else {

                href = currentURL.split('-')[2];
            }

            return Number(href) || -1;
        };

        /**
         * 根据 url 获取已渲染的 dom 的 html 代码
         */
        getFrameHtml(url) {
            return new Promise((resolve, reject) => {
                const iframe = top.document.createElement('iframe');
                iframe.src = url;
                // iframe.sandbox = "allow-scripts allow-same-origin";
                iframe.setAttribute('style', `

position:fixed;
width:0;
height:0;
overflow:hidden;
opacity:0;
`);
                top.document.body.appendChild(iframe);
                const framesLength = top.frames.length;
                iframe.onload = () => {
                    try {
                        const lastWindow = top.frames[framesLength - 1] || top;
                        const divs = lastWindow.document.querySelectorAll('.comiis_postli.comiis_list_readimgs.nfqsqi');

                        const bottomDiv = lastWindow.document.querySelector('.comiis_multi_box.bg_f.b_t.b_b.mb10');

                        // console.log(bottomDiv);
                        // const divArray = Array.from(divs).map(div => div.outerHTML);
                        resolve([divs, bottomDiv]);

                    } catch (error) {
                        popup.open('自动上下页加载失败啦 ˃ʍ˂', 'alert');
                        console.log(error);
                    } finally {
                        this.isRequesting = false;
                        top.document.body.removeChild(iframe);
                    };
                };

            });
        };
        /**
         * 添加样式
         */
        addStyle(css) {
            const style = document.querySelector('style') || document.createElement('style');
            style.innerHTML += css;
        };
        /**
         * 防抖函数
         */
        debounce(fn, delay) {
            let timer = null;
            return function() {
                clearTimeout(timer);
                timer = setTimeout(() => {
                    fn.apply(this, arguments);
                }, delay);
            };
        };
        /**
         * 添加加載下一頁按鈕
         */
        createDynamicLayout(onLoadPage, topPx) {
            // 創建一個新的 div 元素
            var newDiv = document.createElement('div');
            newDiv.className = 'comiis_multi_box comiis_multi_box_1 fooy bg_f b_t';
            newDiv.style.marginTop = topPx || '10px';

            // 創建一個新的 a 元素
            var newLink = document.createElement('a');
            // newLink.href = 'javascript:;';
            newLink.onclick = () => {
                //alert("123");
                try {
                  // alert(onLoadPage());
                   // onLoadPage();
                   if (onLoadPage == 1) {
                       this.loadNextPage();
                   } else {
                      // alert("123");
                       this.loadPreviousPage();
                   };
                } catch (error) {

                    console.log(error);
                };
                // this.init();
                // this.isRequesting = false;
            };
            newLink.className = 'comiis_loadbtn bg_e f_d';
            newLink.textContent = '正在加载，点击或重新下拉重试';

            // 添加 a 元素到 div 元素
            newDiv.appendChild(newLink);

            // 將新的 div 元素添加到適當的位置，比如body的末尾
            // targetDiv.appendChild(newDiv);

            return newDiv

        };
        /**
         * 加载下一页
         */
        loadNextPage() {

            if (this.isRequesting) {
                return;
            };


            /* 链接类 */
            const nextPageUrl = this._getNextPageUrl();

            if (nextPageUrl == '' || nextPageUrl.includes("javascript")) {
                return;
            };

            if (!this.isDynamicLayout) {
                this.isDynamicLayout = this.createDynamicLayout(1);
                top.document.querySelector('.comiis_postlist.kqide')
                    .appendChild(this.isDynamicLayout);
            };

            console.log('链接类：加载下一页', nextPageUrl);
            this.isRequesting = true;
            this.getFrameHtml(nextPageUrl)
                .then(values => {


                if (this.isDynamicLayout) {
                    this.isDynamicLayout.parentNode.removeChild(this.isDynamicLayout);
                    this.isDynamicLayout = null;
                };


                this.lastScrollHeight = top.document.documentElement.scrollHeight;

                const targetDiv = top.document.querySelector('.comiis_postlist.kqide'); // 选择目标 div 元素
                const[divArray, bottomDiv] = values;

                // alert(bottomDiv.outerHTML);

                const bottomTargetDiv = top.document.querySelector('.comiis_multi_box.bg_f.b_t.b_b.mb10');
                bottomTargetDiv.replaceWith(bottomDiv); // cloneNode(true)使用 cloneNode 来复制底部 div，以避免移动原始元素

                divArray.forEach(div => {
                    // console.log(div);
                    targetDiv.appendChild(div); // 将每个 div 元素作为目标 div 的子元素添加
                });



                popup.init();

                // page.converthtml();

                $('#dumppage')
                    .on('change', function() {
                    var href = nextPageUrl;
                    if (href.indexOf('page=') > 0) {

                        window.location.href = href.replace(/page=\d+/, 'page=' + $(this)
                            .val());
                    } else {
                        var comiis_pnum = (href.split('-'))
                            .length - 1;
                        if (comiis_pnum == 3) {

                            window.location.href = href.replace(/-(\d+)-(\d+)-(\d+)\.html/, "-$1-" + $(this)
                                .val() + "-$3.html");
                        } else {
                            window.location.href = href.replace(/-(\d+)-(\d+)\.html/, "-$1-" + $(this)
                                .val() + ".html");
                        }
                    }
                });

            });
        };

        /**
         * 加载上一页
         */
        loadPreviousPage() {

            if (this.isRequesting) {
                return;
            };

            if (!document.querySelectorAll('.comiis_postli.comiis_list_readimgs.nfqsqi')[0].querySelector(".comiis_postli_top.bg_f.b_t")) {
                return;
            };

            /* 链接类 */
            if (!this.previousPageUrl) {
                this.previousPageUrl = this._getPreviousPageUrl();
            };

            if (this.previousPageUrl <= 1) {
                return;
            };

            const href = window.location.href;

            let previousPageUrl2 = '';

            if (href.indexOf('page=') > 0) {

                previousPageUrl2 = href.replace(/page=\d+/, `page=${ this.previousPageUrl - 1 }`);
            } else {
                var comiis_pnum = (href.split('-'))
                    .length - 1;
                if (comiis_pnum == 3) {

                    previousPageUrl2 = href.replace(/-(\d+)-(\d+)-(\d+)\.html/, `-$1-${ this.previousPageUrl - 1 }-$3.html`);
                } else {
                    previousPageUrl2 = href.replace(/-(\d+)-(\d+)\.html/, `-$1-${ this.previousPageUrl - 1 }.html`);
                }
            }

            if (!this.isDynamicLayout) {
                this.isDynamicLayout = this.createDynamicLayout(2, "0");
                const firstElement = document.querySelector('.comiis_postlist.kqide .comiis_postli.comiis_list_readimgs.nfqsqi');
                firstElement.parentNode.insertBefore(this.isDynamicLayout, firstElement);
            };

            console.log('链接类：加载上一页', previousPageUrl2);

            // const topElement = document.querySelectorAll('.comiis_postli.comiis_list_readimgs.nfqsqi')[0];

            this.isRequesting = true;

            this.getFrameHtml(previousPageUrl2)
                .then(values => {


                this.lastScrollHeight = top.document.documentElement.scrollHeight;

                const targetDiv = top.document.querySelector('.comiis_postlist.kqide'); // 选择目标 div 元素
                const[divArray, bottomDiv] = values;

                // alert(bottomDiv.outerHTML);


                // 将 NodeList 转换为数组
                let divArray2 = Array.from(divArray);

                // 反转数组
                divArray2.reverse();

                divArray2.forEach(div => {
                    // console.log(div);
                    targetDiv.insertBefore(div, targetDiv.firstChild); // 将每个 div 元素作为目标 div 的子元素添加
                });

                this.previousPageUrl = this.previousPageUrl - 1

                 if (this.isDynamicLayout) {
                    this.isDynamicLayout.scrollIntoView();
                    this.isDynamicLayout.parentNode.removeChild(this.isDynamicLayout);
                    this.isDynamicLayout = null;
                };


                popup.init();

                // page.converthtml();

                $('#dumppage')
                    .on('change', function() {

                    if (href.indexOf('page=') > 0) {

                        window.location.href = href.replace(/page=\d+/, 'page=' + $(this)
                            .val());
                    } else {
                        var comiis_pnum = (href.split('-'))
                            .length - 1;
                        if (comiis_pnum == 3) {

                            window.location.href = href.replace(/-(\d+)-(\d+)-(\d+)\.html/, "-$1-" + $(this)
                                .val() + "-$3.html");
                        } else {
                            window.location.href = href.replace(/-(\d+)-(\d+)\.html/, "-$1-" + $(this)
                                .val() + ".html");
                        }
                    }
                });

            });

            //alert(previousPageUrl);
        };
    };

    try {
        const configs = [{
            sites: ['bbs.binmt.cc'],
            style: ``,
            getNextPageUrl() {

                const nextPageNodes = document.querySelectorAll('a.bg_f.b_ok');
                const nextPageNode = nextPageNodes[nextPageNodes.length - 1];
                const nextPageLink = nextPageNode && nextPageNode.getAttribute('href') || '';

                return nextPageLink;
            }
        }];

        if (document.readyState === 'complete') {
            new AutoNextPage(configs);
            return;
        };
        window.addEventListener('load', () => {
            new AutoNextPage(configs);
        });
    } catch (err) {
        console.log(':自动拼接下一页：', err);
    };
})();
};
